import { expect, test } from 'tstyche';

interface IChild {
  name: string;
}
const childSchema = new Schema<IChild>({ name: String });
const ChildModel = model<IChild>('SChild', childSchema);
type ChildDoc = HydratedDocFromModel<typeof ChildModel>;

interface IParent {
  name: string;
  children: Types.ObjectId[];
}
const parentSchema = new Schema<IParent>({
  name: String,
  children: [{ type: Schema.Types.ObjectId, ref: 'SChild' }]
});
const ParentModel = model<IParent>('SParent', parentSchema);

test('populate toObject', async () => {
  const doc = await ParentModel.findOne().orFail().populate<{ children: Types.DocumentArray<ChildDoc> }>('children');

  // Populated result must NOT be assignable to the un-populated hydrated type
  expect(doc).type.not.toBeAssignableTo<HydratedDocFromModel<typeof ParentModel>>();

  // No options -> populated shape
  const obj = doc.toObject();
  expect(obj.children[0].name).type.toBe<string>();

  // depopulate: true -> original ObjectId
  const dep = doc.toObject({ depopulate: true });
  expect(dep.children![0]).type.toBe<Types.ObjectId>();

  // depopulate + flattenObjectIds -> string
  const flat = doc.toObject({ depopulate: true, flattenObjectIds: true });
  expect(flat.children![0]).type.toBe<string>();

  // Strip the marker -> base behavior (ObjectId)
  const stripped = {} as Omit<typeof doc, keyof import('mongoose').PopulatedDocumentMarker<any, any>>;
  const strippedObj = stripped.toObject();
  expect(strippedObj.children[0]).type.toBe<Types.ObjectId>();
});
